insert into public.artigos
 (slug,pasta,status,h1,title_seo,descricao,keywords,badge,autor,tempo_leitura,
  lead,por_tras,quando,quando_nota,profissionais,em_casa)
values
('meu-filho-nao-fala','sinais','publicado','Meu filho não fala: o que pode estar acontecendo','Meu filho não fala: quando se preocupar e o que fazer','Criança de 2 ou 3 anos que não fala: o que é esperado para cada idade, quando procurar avaliação e o que dá para fazer em casa esta semana.','meu filho não fala, criança de 2 anos não fala, criança de 3 anos não fala, atraso de fala, quando se preocupar com a fala','Linguagem e Fala','Equipe Neuroplasticidar','6 min de leitura','Se seu filho já passou da idade em que os primos e coleguinhas começaram a falar e ele ainda não fala — ou fala muito pouco — a pergunta que não sai da cabeça é se dá para esperar mais um pouco ou se é hora de procurar alguém. Esta página não vai te dar um diagnóstico. Vai te dar referência para saber se o que você está vendo pede avaliação, e o que fazer enquanto isso.','[{"titulo": "Ritmo próprio de desenvolvimento", "texto": "Existe uma faixa larga de normalidade. Parte das crianças que falam tarde alcança os colegas sozinha, sem intervenção nenhuma. O problema é que não dá para saber de antemão qual criança é essa — e esperar custa tempo de estimulação."}, {"titulo": "Dificuldade de audição", "texto": "É a primeira coisa a descartar, sempre. Otite de repetição, perda auditiva leve ou flutuante deixam a criança ouvindo pouco justamente na fase em que ela precisa ouvir muito para aprender a falar."}, {"titulo": "Atraso específico de linguagem", "texto": "A criança entende o que você fala, mostra interesse, se comunica por gesto e olhar — mas a fala não sai no ritmo esperado. Costuma responder bem a fonoaudiologia."}, {"titulo": "Sinal dentro de um quadro mais amplo", "texto": "Quando a fala atrasada vem junto de pouco contato visual, pouco interesse por outras crianças ou brincadeira sempre repetitiva, a avaliação precisa olhar o conjunto, não só a fala."}]'::jsonb,'["Aos 12 meses: não balbucia, não aponta, não faz tchau nem manda beijo.", "Aos 18 meses: não fala nenhuma palavra com intenção além de mamã e papá.", "Aos 2 anos: tem menos de 50 palavras ou não junta duas palavras (quer água, cadê mamãe).", "Aos 3 anos: não monta frases curtas, ou quase ninguém de fora da família entende o que ela fala.", "Em qualquer idade: perdeu palavras que já dizia antes. Esse é o único item da lista que é urgente."]'::jsonb,'Esses marcos são referência geral e existe variação normal entre crianças. Se um item bateu com o que você vive, isso não significa diagnóstico — significa que vale marcar uma avaliação em vez de esperar.','[{"titulo": "Fonoaudiólogo", "texto": "É quem avalia e trata linguagem e fala. Na maioria dos casos, é por aqui que se começa."}, {"titulo": "Otorrinolaringologista", "texto": "Para descartar perda auditiva antes de qualquer outra coisa. Peça o exame mesmo que ela pareça ouvir bem."}, {"titulo": "Neuropediatra", "texto": "Quando a fala vem junto de outros sinais no desenvolvimento e é preciso olhar o quadro inteiro."}]'::jsonb,'[{"titulo": "Narre o que você está fazendo", "texto": "Fale em voz alta o que acontece no banho, na comida, no caminho da escola. Criança aprende palavra ouvindo palavra ligada à coisa acontecendo na frente dela."}, {"titulo": "Espere depois de perguntar", "texto": "Conte até cinco em silêncio depois de fazer uma pergunta. Adulto costuma responder pela criança antes que ela tenha tempo de tentar."}, {"titulo": "Não entregue antes do pedido", "texto": "Se ela aponta para o suco, segure um instante e nomeie: suco. Você quer suco? Dar espaço para a tentativa é o que cria a necessidade de falar."}, {"titulo": "Reduza tela e aumente chão", "texto": "Vídeo não ensina a falar porque não responde. O que ensina é gente respondendo — mesmo que a resposta dela seja só um som."}]'::jsonb),
('crianca-nao-para-quieta','sinais','publicado','Criança que não para quieta: energia ou sinal de alguma coisa?','Criança que não para quieta: quando é energia e quando é sinal','Criança agitada que não senta, não termina nada e parece ter um motor ligado. O que costuma estar por trás, quando avaliar e o que fazer em casa.','criança que não para quieta, criança muito agitada, criança hiperativa, criança não senta, criança não termina nada','Atenção e Regulação','Equipe Neuroplasticidar','6 min de leitura','A escola já comentou. Em festa de família alguém já falou. E em casa você repete a mesma frase vinte vezes por dia sem que nada mude. Antes de tratar isso como falta de limite, vale entender o que está por trás — porque agitação quase nunca é só teimosia.','[{"titulo": "Necessidade de movimento não atendida", "texto": "Corpo que passou o dia sentado precisa se descarregar. Muitas vezes o que parece agitação é uma criança pedindo movimento no único momento em que consegue: na hora errada."}, {"titulo": "Desregulação sensorial", "texto": "Algumas crianças buscam estímulo o tempo todo — correm, batem, se jogam, apertam. Não é excesso de energia; é o corpo procurando informação que não está chegando de outro jeito."}, {"titulo": "Dificuldade de função executiva", "texto": "Iniciar, sustentar e trocar de tarefa depende de um conjunto de habilidades que amadurece devagar. Quando ela não termina nada, muitas vezes não é falta de vontade: é falta de ferramenta."}, {"titulo": "Fuga de uma tarefa difícil", "texto": "Criança que não consegue fazer costuma sair de perto. Agitação que aparece só na hora da lição, e não no parque, quase sempre está falando de dificuldade, não de energia."}]'::jsonb,'["A agitação aparece em todos os lugares — casa, escola, casa de parente — e não só num deles.", "Ela se machuca com frequência por não medir risco nem esperar.", "Não consegue sustentar nem uma brincadeira de que gosta muito por alguns minutos.", "A escola já procurou você mais de uma vez pelo mesmo motivo.", "Está sofrendo com isso: sendo excluída, ouvindo que é bagunceira, começando a se descrever assim."]'::jsonb,'Agitação em um contexto só (só na escola, só na aula de um professor) fala mais do contexto do que da criança. É a agitação que atravessa todos os ambientes que pede avaliação.','[{"titulo": "Neuropsicopedagogo", "texto": "Avalia atenção, funções executivas e como isso está afetando a aprendizagem."}, {"titulo": "Terapeuta ocupacional", "texto": "Investiga o componente sensorial: se o corpo está buscando ou evitando estímulo."}, {"titulo": "Neuropediatra ou psiquiatra infantil", "texto": "Quando é preciso investigar TDAH e descartar outras causas."}]'::jsonb,'[{"titulo": "Movimento antes da tarefa, não depois", "texto": "Dez minutos de correr, pular ou empurrar algo pesado antes de sentar rendem mais que trinta minutos de insistência depois."}, {"titulo": "Uma instrução por vez", "texto": "Troque pega o material, senta e começa por pega o material. E só depois a próxima. Instrução em bloco se perde no meio."}, {"titulo": "Diminua o tempo, não a exigência", "texto": "Cinco minutos de tarefa terminada valem mais que vinte minutos de tarefa abandonada. Aumente aos poucos a partir do que ela consegue de verdade."}, {"titulo": "Avise a transição antes", "texto": "Faltam dois minutos para guardar. Boa parte da explosão não é sobre a atividade — é sobre ser interrompida sem aviso."}]'::jsonb),
('crianca-nao-olha-nos-olhos','sinais','publicado','Criança que não olha nos olhos: o que isso pode significar','Criança que não olha nos olhos: o que pode ser e quando avaliar','Pouco contato visual na infância: o que costuma estar por trás, quais outros sinais observar junto e quando procurar avaliação.','criança não olha nos olhos, pouco contato visual, criança não atende pelo nome, sinais de autismo, criança não responde quando chamada','Desenvolvimento Atípico','Equipe Neuroplasticidar','6 min de leitura','Contato visual é uma das primeiras coisas que a gente nota — e uma das que mais assusta quando falta. Vale dizer de saída: olhar pouco, sozinho, não define nada. O que importa é o conjunto, e é isso que esta página ajuda você a observar antes da consulta.','[{"titulo": "Temperamento e timidez", "texto": "Existe criança que olha menos e se comunica muito bem — pelo corpo, pelo gesto, pela fala. Se ela busca você, mostra coisas, divide o que achou engraçado, o olhar curto pesa pouco."}, {"titulo": "Desconforto sensorial", "texto": "Para algumas crianças, sustentar o olhar é estímulo demais. Elas não estão desligadas; estão regulando. Costumam olhar mais quando o ambiente está mais calmo."}, {"titulo": "Dificuldade de atenção compartilhada", "texto": "Aqui o sinal é mais específico: ela não segue o seu dedo quando você aponta, não olha para conferir a sua reação, não mostra coisas só para dividir. Isso pesa mais que o contato visual em si."}, {"titulo": "Sinal dentro de um quadro de desenvolvimento", "texto": "Pouco olhar junto de não atender pelo nome, brincadeira sempre igual e pouco interesse por outras crianças forma um conjunto que pede avaliação — sem que isso já signifique diagnóstico."}]'::jsonb,'["Não atende pelo nome aos 12 meses, mesmo ouvindo bem.", "Não aponta para mostrar coisas — só para pedir, ou nem isso.", "Não olha para conferir a sua reação diante de algo novo.", "Não mostra interesse por outras crianças, nem de longe.", "Repete sempre a mesma brincadeira do mesmo jeito e se incomoda muito se você muda algo."]'::jsonb,'Dois ou mais itens acontecendo juntos e de forma consistente é o que muda a conversa. Um item isolado, num dia ruim, não é sinal — é infância.','[{"titulo": "Neuropediatra", "texto": "Coordena a avaliação do desenvolvimento como um todo e é quem costuma emitir o laudo."}, {"titulo": "Psicólogo infantil", "texto": "Avalia interação, comunicação social e brincadeira."}, {"titulo": "Fonoaudiólogo", "texto": "Entra pela comunicação — que é bem mais ampla que fala."}]'::jsonb,'[{"titulo": "Fique na altura dos olhos", "texto": "Sentar no chão de frente para ela muda muito mais o contato visual do que pedir olha para mim."}, {"titulo": "Não exija o olhar como condição", "texto": "Cobrar olha aqui antes de dar o brinquedo transforma o olhar em obrigação. O caminho é o contrário: torne olhar para você a coisa mais interessante que está acontecendo."}, {"titulo": "Entre na brincadeira dela", "texto": "Faça junto o que ela já está fazendo, do jeito dela, por alguns minutos, sem redirecionar. O olhar costuma vir depois de a criança perceber que você é parte divertida do que ela gosta."}, {"titulo": "Crie pausa no meio da diversão", "texto": "Empurre o carrinho, empurre de novo, e na terceira segure e espere. A pausa é o que faz ela procurar você."}]'::jsonb),
('crianca-explode-bate-descontrola','sinais','publicado','Criança que explode, bate e se descontrola','Criança que explode e bate: por que acontece e como agir','Crises intensas, agressividade e descontrole na infância: o que costuma disparar, como agir na hora e quando procurar ajuda.','criança que bate, criança agressiva, crise de birra, criança se descontrola, criança explode por qualquer coisa','Regulação Emocional','Equipe Neuroplasticidar','6 min de leitura','Uma coisa é a birra que passa em dois minutos. Outra é a crise que dura quarenta, em que ela bate, se joga, quebra coisa e depois nem sabe explicar o que aconteceu. Se você está vivendo a segunda, o que você precisa não é de mais firmeza — é de entender o que dispara.','[{"titulo": "Falta de vocabulário para o que sente", "texto": "Criança que não consegue dizer estou com raiva, estou com medo, é demais para mim usa o corpo. Quanto menor o repertório de palavras para emoção, maior a chance de explosão."}, {"titulo": "Sobrecarga sensorial", "texto": "Barulho, luz, gente demais, roupa incomodando. A crise que parece vir do nada muitas vezes vem do acúmulo — e o gatilho final foi só a última gota."}, {"titulo": "Transição sem aviso", "texto": "Ser tirada do que estava fazendo é um dos disparadores mais comuns e um dos mais fáceis de evitar."}, {"titulo": "Comunicação que não funciona", "texto": "Quando pedir não resolve, gritar e bater resolvem — pelo menos aos olhos dela. Boa parte da agressividade é uma comunicação que aprendeu a funcionar por falta de alternativa."}]'::jsonb,'["As crises passam de vinte minutos com frequência.", "Ela se machuca ou machuca outra pessoa.", "Acontecem várias vezes por semana e vêm aumentando.", "Depois da crise ela parece exausta ou confusa, sem entender o que houve.", "Está afetando a vida: convite que não vem mais, escola ligando, família andando em ovos."]'::jsonb,'Frequência e intensidade importam mais que o motivo. Toda criança tem crise; o que pede avaliação é quando elas passam a organizar a rotina da casa em torno de evitá-las.','[{"titulo": "Psicólogo infantil", "texto": "Trabalha regulação emocional com a criança e orientação com os pais."}, {"titulo": "Terapeuta ocupacional", "texto": "Quando o gatilho é sensorial, mexer no ambiente resolve mais que qualquer conversa."}, {"titulo": "Supervisor ABA", "texto": "Quando o comportamento tem função clara e é preciso ensinar uma alternativa que funcione melhor para ela."}]'::jsonb,'[{"titulo": "Durante a crise, menos palavra", "texto": "No pico, ela não está processando argumento. Fique perto, garanta segurança, fale pouco e baixo. Conversa depois, quando o corpo já baixou."}, {"titulo": "Nomeie a emoção quando estiver calma", "texto": "Você ficou com muita raiva quando o jogo acabou. Nomear fora da crise é o que constrói o vocabulário que ela vai usar dentro da próxima."}, {"titulo": "Anote os gatilhos por duas semanas", "texto": "Hora, lugar, o que aconteceu antes. O padrão quase sempre aparece — e quase sempre é mais previsível do que parecia."}, {"titulo": "Ensine o que fazer, não só o que não fazer", "texto": "Não bata deixa um vazio. Vem me chamar quando estiver assim entrega uma saída. Criança precisa de substituto, não só de proibição."}]'::jsonb),
('crianca-brinca-sozinha','sinais','publicado','Criança que só brinca sozinha e evita outras crianças','Criança que brinca sozinha: quando é jeito e quando é sinal','Criança que prefere brincar sozinha, não entra em grupo e repete sempre a mesma brincadeira. O que observar e quando procurar avaliação.','criança brinca sozinha, criança não interage com outras crianças, criança isolada na escola, criança não faz amigos','Interação Social','Equipe Neuroplasticidar','6 min de leitura','Tem criança que gosta de sossego e brinca muito bem sozinha — e isso não é problema nenhum. O que merece um olhar mais atento é quando ela não consegue entrar no grupo mesmo querendo, ou quando a brincadeira sozinha é sempre exatamente a mesma.','[{"titulo": "Temperamento mais reservado", "texto": "Existe criança que observa muito antes de entrar, e entra quando se sente segura. Se ela entra depois de um tempo e se diverte, está tudo bem."}, {"titulo": "Não sabe como entrar", "texto": "Muita criança quer participar e não tem o repertório: como pedir para brincar, como esperar a vez, como lidar com o não. É uma habilidade que se ensina."}, {"titulo": "Brincadeira ainda no estágio anterior", "texto": "Se ela alinha, empilha e organiza mas não faz de conta, o faz de conta pode ainda não ter chegado — e é justamente ele que abre a porta da brincadeira compartilhada."}, {"titulo": "Dificuldade de comunicação social", "texto": "Quando o isolamento vem com pouco contato visual, pouca fala e desinteresse consistente por outras crianças, o conjunto pede avaliação."}]'::jsonb,'["Não demonstra interesse por outras crianças nem de longe, em nenhum contexto.", "Repete sempre a mesma brincadeira, do mesmo jeito, e se irrita se alguém muda algo.", "Não faz faz de conta depois dos 3 anos — não dá comidinha para boneca, não finge que o bloco é carro.", "Tenta entrar no grupo, é rejeitada, e já parou de tentar.", "A professora relata que ela fica sozinha o recreio inteiro, todos os dias."]'::jsonb,'Gostar de brincar sozinha é diferente de não conseguir brincar junto. A pergunta que separa as duas: quando outra criança convida, ela vai?','[{"titulo": "Psicólogo infantil", "texto": "Trabalha habilidades sociais e a experiência da criança nesse isolamento."}, {"titulo": "Terapeuta ocupacional", "texto": "Entra pelo brincar — inclusive pelo desenvolvimento do faz de conta."}, {"titulo": "Fonoaudiólogo", "texto": "Quando a barreira para entrar no grupo é de comunicação."}]'::jsonb,'[{"titulo": "Brinque junto sem comandar", "texto": "Sente do lado e faça o que ela está fazendo, no ritmo dela, sem sugerir nada por alguns minutos. Brincar junto se aprende primeiro com adulto."}, {"titulo": "Convide uma criança só", "texto": "Grupo grande é difícil demais para quem está aprendendo. Uma criança, em casa, com atividade definida, funciona muito melhor que festa."}, {"titulo": "Introduza o faz de conta pelo concreto", "texto": "Comece pelo que imita a vida real: dar comida ao urso, telefone de mentira, colocar a boneca para dormir. O simbólico começa pelo cotidiano."}, {"titulo": "Ensaie a entrada", "texto": "Treine em casa a frase de entrar: posso brincar? Parece pequeno e é exatamente o que costuma faltar na hora."}]'::jsonb),
('crianca-nao-aprende-ler','sinais','publicado','Criança que não aprende a ler e escrever','Criança que não aprende a ler: o que pode estar travando','Criança que não consegue acompanhar a alfabetização: o que costuma estar por trás, quando avaliar e o que trabalhar antes de insistir na leitura.','criança não aprende a ler, dificuldade de alfabetização, criança troca letras, dislexia infantil, criança não acompanha a turma','Aprendizagem','Equipe Neuroplasticidar','6 min de leitura','A turma inteira avançou e ela ficou. Você já tentou reforço, já tentou em casa, já tentou com paciência e sem paciência. Antes de repetir mais do mesmo, vale entender o que costuma travar a alfabetização — porque quase sempre o problema está num degrau anterior à leitura.','[{"titulo": "Consciência fonológica não construída", "texto": "Antes de ler, a criança precisa perceber que a palavra é feita de sons: que casa e cavalo começam igual, que bo-ne-ca tem três pedaços. Sem esse degrau, decorar letra não vira leitura."}, {"titulo": "Vocabulário insuficiente", "texto": "É difícil ler uma palavra que você nunca ouviu. Vocabulário pobre trava a leitura mesmo quando a decodificação vai bem."}, {"titulo": "Atenção e memória de trabalho", "texto": "Ler exige segurar o começo da palavra na cabeça enquanto decodifica o fim. Quando a memória de trabalho é curta, a frase se perde no meio."}, {"titulo": "Dificuldade específica de aprendizagem", "texto": "Troca persistente de letras, leitura muito lenta e esforço desproporcional ao resultado, apesar de ensino adequado, pedem avaliação específica."}]'::jsonb,'["Aos 6 anos não reconhece a maioria das letras nem o som delas.", "Aos 7 anos ainda lê soletrando letra por letra, sem juntar.", "Troca, inverte ou omite letras de forma persistente, muito além dos colegas.", "Lê a frase inteira e não sabe dizer o que leu.", "Já criou aversão: chora, foge, diz que é burra na hora de ler."]'::jsonb,'O último item é o mais importante da lista. Dificuldade se recupera; a crença de que não é capaz custa muito mais caro e demora muito mais para desfazer.','[{"titulo": "Neuropsicopedagogo", "texto": "Avalia como ela aprende e onde exatamente o processo está travando."}, {"titulo": "Fonoaudiólogo", "texto": "Trabalha consciência fonológica e linguagem — a base sobre a qual a leitura se apoia."}, {"titulo": "Psicólogo", "texto": "Quando já existe sofrimento, recusa ou queda de autoestima ligada à escola."}]'::jsonb,'[{"titulo": "Brinque com som antes de brincar com letra", "texto": "Qual palavra começa igual a bola? Quantos pedaços tem bo-la? Isso vale mais, nessa fase, que qualquer cartilha."}, {"titulo": "Leia para ela, mesmo que ela já devesse ler sozinha", "texto": "Ouvir história constrói vocabulário e mantém o gosto de pé enquanto a habilidade não vem."}, {"titulo": "Sessões curtas e diárias", "texto": "Dez minutos por dia rendem mais que uma hora no domingo — e machucam muito menos a relação dela com a leitura."}, {"titulo": "Separe o esforço do resultado", "texto": "Elogie ter tentado, não ter acertado. Quem se sente burro para de tentar, e aí nenhuma técnica funciona."}]'::jsonb),
('crianca-incomoda-barulho-textura','sinais','publicado','Criança que se incomoda com barulho, textura e toque','Criança que se incomoda com barulho e textura: o que pode ser','Tapa o ouvido, não come certas texturas, não tolera etiqueta na roupa: o que é desregulação sensorial, quando avaliar e como adaptar o dia a dia.','criança tapa o ouvido, criança não gosta de barulho, seletividade alimentar, criança não gosta de ser tocada, sensibilidade sensorial infantil','Sensorial','Equipe Neuroplasticidar','6 min de leitura','Tapa o ouvido no aniversário. Não come nada molinho. Chora com a etiqueta da roupa e não deixa cortar a unha. Isso não é frescura nem manha — é um sistema sensorial recebendo informação com intensidade diferente da sua. E tem muito o que fazer a respeito.','[{"titulo": "Hipersensibilidade", "texto": "O estímulo chega mais forte do que chegaria para você. Barulho de liquidificador, luz de shopping, etiqueta de camiseta: para ela é volume alto, não é implicância."}, {"titulo": "Seletividade alimentar de base sensorial", "texto": "Recusa quase sempre ligada a textura, cheiro ou temperatura, e não ao alimento em si. Por isso ela aceita a mesma fruta crua e recusa cozida."}, {"titulo": "Defensividade tátil", "texto": "Toque leve e inesperado incomoda mais que toque firme. É por isso que o abraço apertado passa e o encostar de leve na fila irrita."}, {"titulo": "Sinal dentro de um quadro mais amplo", "texto": "Alterações sensoriais são muito frequentes no autismo e no TDAH, mas também aparecem isoladas, sem nenhum outro sinal junto."}]'::jsonb,'["A reação atrapalha a vida: não dá para ir a festa, a mercado, a restaurante.", "Come menos de quinze alimentos diferentes, e a lista vem encolhendo.", "Banho, corte de cabelo ou corte de unha viram crise toda vez.", "Ela se afasta de brincadeira que gostaria de fazer por causa do barulho ou do toque.", "Está perdendo peso ou faltando nutriente por causa da restrição alimentar."]'::jsonb,'O último item pede avaliação com pediatra sem esperar. Os outros pedem terapia ocupacional — e costumam responder bem.','[{"titulo": "Terapeuta ocupacional", "texto": "É a especialidade que avalia e trata integração sensorial. Para essa queixa, é por aqui que se começa."}, {"titulo": "Fonoaudiólogo", "texto": "Quando a seletividade alimentar envolve também mastigação e deglutição."}, {"titulo": "Nutricionista infantil", "texto": "Quando a restrição já está afetando crescimento ou exame."}]'::jsonb,'[{"titulo": "Avise antes de tocar", "texto": "Vou cortar sua unha agora reduz muito a reação. O que dispara costuma ser o inesperado, não o toque em si."}, {"titulo": "Ofereça pressão profunda", "texto": "Abraço firme, almofada em cima, rolar enrolada no lençol. Pressão profunda organiza, enquanto toque leve alerta."}, {"titulo": "Aproxime o alimento sem exigir comer", "texto": "Deixe no prato, deixe tocar, deixe cheirar, deixe rejeitar sem drama. A exposição sem pressão é o que amplia o repertório — obrigar costuma reduzir."}, {"titulo": "Crie um canto de descanso", "texto": "Lugar com pouca luz e pouco barulho onde ela possa ir antes de explodir. Sair do estímulo é habilidade, não fuga."}]'::jsonb),
('crianca-nao-se-veste-sozinha','sinais','publicado','Criança que não se veste, não come sozinha e depende para tudo','Criança que não se veste sozinha: o que é esperado por idade','Autonomia na infância: o que se espera em cada idade para vestir, comer e higiene, o que costuma travar e como ensinar em casa.','criança não se veste sozinha, criança não come sozinha, autonomia infantil por idade, criança dependente para tudo, atividades de vida diária criança','Autonomia','Equipe Neuroplasticidar','6 min de leitura','Ela já tem idade, os colegas já fazem, e em casa ainda é você que veste, que dá comida na boca e que escova o dente. Muitas vezes o que trava não é a criança — é que ninguém ensinou por partes. Mas às vezes tem algo por trás, e vale saber distinguir.','[{"titulo": "Nunca teve a oportunidade", "texto": "Adulto com pressa faz mais rápido, e por isso faz. É a causa mais comum e a mais fácil de resolver: a criança não aprendeu porque nunca precisou."}, {"titulo": "Coordenação motora fina ainda imatura", "texto": "Botão, zíper, cadarço e talher exigem precisão de dedos. Quando a mão ainda não dá conta, ela desiste antes de tentar."}, {"titulo": "Dificuldade de sequenciar", "texto": "Vestir tem ordem: cabeça, braço, braço, puxar. Criança que se perde na sequência trava no meio e parece preguiça."}, {"titulo": "Componente sensorial", "texto": "Roupa que incomoda, escova que raspa, água na cabeça. Aqui a recusa não é de autonomia, é de sensação — e o caminho é outro."}]'::jsonb,'["Aos 3 anos não tenta tirar peça simples de roupa nem segura a colher.", "Aos 4 anos não se veste com peça fácil, mesmo com ajuda no começo.", "Aos 5 anos ainda depende integralmente para comer, vestir e higiene.", "Ela tenta, se frustra rápido e desiste sempre no mesmo ponto.", "A dependência vem junto de outros atrasos de desenvolvimento."]'::jsonb,'Idades são referência, com variação normal entre crianças. O sinal mais informativo não é a idade — é a criança tentar e travar sempre no mesmo passo.','[{"titulo": "Terapeuta ocupacional", "texto": "É a especialidade das atividades de vida diária. Avalia se o que trava é motor, sensorial ou de sequência."}, {"titulo": "Neuropsicopedagogo", "texto": "Quando a dificuldade é de planejar e sustentar a sequência de passos."}, {"titulo": "Neuropediatra", "texto": "Quando a dependência aparece junto de outros atrasos e é preciso olhar o conjunto."}]'::jsonb,'[{"titulo": "Ensine de trás para frente", "texto": "Você veste quase tudo e deixa o último passo para ela — puxar a blusa, fechar o zíper. Terminar sozinha dá a sensação de conta feita e sustenta a próxima tentativa."}, {"titulo": "Facilite a peça antes de facilitar a tarefa", "texto": "Elástico em vez de botão, velcro em vez de cadarço. Vença primeiro a sequência; a peça difícil vem depois."}, {"titulo": "Sequência visual na parede", "texto": "Quatro fotos na ordem, no banheiro ou no quarto. Tira de você o papel de repetir e devolve para ela o de conferir."}, {"titulo": "Reserve tempo para ela fazer", "texto": "Dez minutos a mais na manhã são o preço da autonomia. Não dá para ensinar isso com pressa."}]'::jsonb)
on conflict (slug) do update set
  h1=excluded.h1, title_seo=excluded.title_seo, descricao=excluded.descricao,
  keywords=excluded.keywords, badge=excluded.badge, lead=excluded.lead,
  por_tras=excluded.por_tras, quando=excluded.quando, quando_nota=excluded.quando_nota,
  profissionais=excluded.profissionais, em_casa=excluded.em_casa;

-- objetivos e faq (jsonb) em update separado, por slug
update public.artigos set objetivos='["linguagem", "comunicacao", "vocabulario"]'::jsonb, faq='[{"pergunta": "Meu filho tem 2 anos e não fala, mas entende tudo. É normal?", "resposta": "Entender bem é um bom sinal e muda o prognóstico para melhor. Ainda assim, aos 2 anos o esperado é que ela já tenha em torno de 50 palavras e comece a juntar duas. Compreender bem e não falar merece avaliação de fonoaudiologia — normalmente com resposta rápida."}, {"pergunta": "Vale a pena esperar até os 3 anos para procurar ajuda?", "resposta": "Não. A janela de maior plasticidade da linguagem está justamente entre 1 e 3 anos. Avaliar cedo não cria problema onde não tem; só antecipa a solução onde tem."}, {"pergunta": "Ser bilíngue ou assistir muito desenho atrasa a fala?", "resposta": "Bilinguismo não causa atraso de fala — crianças bilíngues podem misturar as línguas por um tempo, o que é diferente de atrasar. Excesso de tela, sim, tira tempo de interação, que é onde a linguagem se constrói."}]'::jsonb, publicado_em=now() where slug='meu-filho-nao-fala';
update public.artigos set objetivos='["funcoes", "sensorial", "motora-grossa"]'::jsonb, faq='[{"pergunta": "Criança agitada é sempre TDAH?", "resposta": "Não. Agitação é um sinal, não um diagnóstico, e aparece em quadros muito diferentes — sensorial, ansiedade, dificuldade de aprendizagem, sono ruim, ou simplesmente uma criança saudável com pouca oportunidade de se mover. Só avaliação distingue."}, {"pergunta": "A partir de que idade dá para investigar?", "resposta": "Antes dos 5 ou 6 anos, muita agitação ainda é esperada para a fase. Isso não impede avaliação — apenas muda o foco: antes dessa idade se olha mais para desenvolvimento global e sensorial do que para diagnóstico de atenção."}, {"pergunta": "Tirar a tela resolve?", "resposta": "Ajuda, mas raramente resolve sozinho. Tela em excesso piora regulação e sono, e o efeito aparece em alguns dias. Se você tirou e nada mudou, é sinal de que tem outra coisa junto."}]'::jsonb, publicado_em=now() where slug='crianca-nao-para-quieta';
update public.artigos set objetivos='["comunicacao", "simbolico", "linguagem"]'::jsonb, faq='[{"pergunta": "Não olhar nos olhos é sinal de autismo?", "resposta": "Pode ser um dos sinais, mas sozinho não define nada. Existe criança autista que mantém contato visual e criança não autista que olha pouco. O que orienta é o conjunto — atenção compartilhada, comunicação, interesse social e brincadeira."}, {"pergunta": "Com que idade dá para avaliar?", "resposta": "A partir de 18 meses já existem instrumentos de rastreio bem estabelecidos, e avaliação de desenvolvimento pode ser feita antes disso. Não existe idade cedo demais para observar; existe tarde demais para começar a estimular."}, {"pergunta": "Se for autismo, começar cedo muda alguma coisa?", "resposta": "Muda bastante. A literatura é consistente em mostrar que intervenção precoce melhora comunicação, autonomia e qualidade de vida. É o argumento mais forte contra a estratégia de esperar para ver."}]'::jsonb, publicado_em=now() where slug='crianca-nao-olha-nos-olhos';
update public.artigos set objetivos='["emocoes", "comunicacao", "funcoes"]'::jsonb, faq='[{"pergunta": "Estou sendo mole demais?", "resposta": "Crise intensa e recorrente raramente é resultado de falta de limite. Endurecer costuma aumentar a frequência, não diminuir. O que muda o quadro é previsibilidade, antecipação e ensinar uma forma de comunicar que funcione."}, {"pergunta": "Devo ignorar a crise?", "resposta": "Ignorar funciona para comportamento que existe só para buscar atenção — e não é a maioria dos casos. Quando a crise vem de sobrecarga ou de não saber se comunicar, ignorar prolonga o sofrimento sem ensinar nada."}, {"pergunta": "Ela bate só em mim. Por quê?", "resposta": "Costuma ser onde ela se sente mais segura para desmoronar. É desgastante e é, ao mesmo tempo, sinal de vínculo. Não significa que você está fazendo errado."}]'::jsonb, publicado_em=now() where slug='crianca-explode-bate-descontrola';
update public.artigos set objetivos='["simbolico", "comunicacao", "emocoes"]'::jsonb, faq='[{"pergunta": "Ela brinca bem sozinha em casa mas fica sozinha na escola. É problema?", "resposta": "Pode ser diferença de ambiente: escola tem mais barulho, mais gente e menos previsibilidade. Vale conversar com a professora sobre o que acontece exatamente no recreio antes de concluir qualquer coisa."}, {"pergunta": "Filho único brinca sozinho por causa disso?", "resposta": "Ter irmão dá mais treino, mas não é o que determina. Filho único com convivência regular com outras crianças desenvolve as mesmas habilidades."}, {"pergunta": "Devo obrigar a participar?", "resposta": "Obrigar costuma aumentar a resistência. Funciona melhor diminuir a dificuldade — menos crianças, ambiente conhecido, atividade com regra clara — do que aumentar a pressão."}]'::jsonb, publicado_em=now() where slug='crianca-brinca-sozinha';
update public.artigos set objetivos='["pre-alfa", "alfa", "vocabulario", "funcoes"]'::jsonb, faq='[{"pergunta": "Com que idade devo me preocupar?", "resposta": "Até os 6 anos existe variação grande e normal. A partir dos 7, dificuldade persistente apesar de ensino adequado é o momento de avaliar, não de esperar mais um ano."}, {"pergunta": "Pode ser dislexia?", "resposta": "Pode, e o diagnóstico é feito por avaliação específica, geralmente com equipe. Só que a conduta inicial é parecida de qualquer forma: fortalecer consciência fonológica e vocabulário. Não é preciso ter o laudo na mão para começar a ajudar."}, {"pergunta": "Reforço escolar resolve?", "resposta": "Resolve quando a dificuldade é de conteúdo. Não resolve quando é de processo — nesse caso, mais do mesmo só aumenta a frustração. Se o reforço não mudou nada em alguns meses, é sinal de que o degrau que falta é anterior."}]'::jsonb, publicado_em=now() where slug='crianca-nao-aprende-ler';
update public.artigos set objetivos='["sensorial", "avd", "emocoes"]'::jsonb, faq='[{"pergunta": "Isso é frescura ou manha?", "resposta": "Não. A resposta sensorial é involuntária — ela não está escolhendo se incomodar. Tratar como manha aumenta a reação e prejudica a relação, porque a criança sente que não está sendo acreditada."}, {"pergunta": "Se eu insistir, ela acostuma?", "resposta": "Insistir sem preparo costuma sensibilizar mais, não menos. O caminho é exposição gradual, previsível e sem pressão — que é exatamente o que a terapia ocupacional estrutura."}, {"pergunta": "Toda criança sensível é autista?", "resposta": "Não. Alterações sensoriais aparecem no autismo com frequência, mas também aparecem sozinhas, em crianças sem nenhum outro sinal. É um sinal a observar, não uma conclusão."}]'::jsonb, publicado_em=now() where slug='crianca-incomoda-barulho-textura';
update public.artigos set objetivos='["avd", "motora-fina", "funcoes"]'::jsonb, faq='[{"pergunta": "Estou fazendo demais por ela?", "resposta": "É a causa mais comum, e a boa notícia é que reverte rápido. Escolha uma tarefa só, ensine de trás para frente e sustente por duas semanas antes de acrescentar outra."}, {"pergunta": "Ela faz na escola e não faz em casa. Por quê?", "resposta": "Costuma ser demanda de ambiente: na escola ninguém faz por ela e existe um modelo de colega fazendo junto. Em casa, o atalho está disponível. Isso é um bom sinal — a habilidade existe."}, {"pergunta": "Até que idade é normal dar comida na boca?", "resposta": "Por volta dos 2 anos a maioria já come sozinha, ainda que sujando bastante. Depois dos 3, dependência total para comer merece um olhar mais atento."}]'::jsonb, publicado_em=now() where slug='crianca-nao-se-veste-sozinha';
